package com.neighbormarket.web;
import com.neighbormarket.service.ExchangeService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api") public class ExchangeController {private final ExchangeService s;public ExchangeController(ExchangeService x){s=x;}
 @GetMapping("/items/{id}/slots") public List<ExchangeService.SlotView> slots(@PathVariable Long id){return s.validSlots(id);} @PostMapping("/items/{id}/pickup-options") public List<ExchangeService.SlotView> configure(@PathVariable Long id,@Valid @RequestBody PickupRequest b,Authentication a){return s.configure(id,b.location(),b.slots(),a.getName());}
 @PostMapping("/items/{id}/interests") public ExchangeService.InterestView want(@PathVariable Long id,@Valid @RequestBody WantRequest b,Authentication a){return s.want(id,b.slotId(),a.getName());} @DeleteMapping("/items/{id}/interests/mine") public ExchangeService.InterestView cancelInterest(@PathVariable Long id,Authentication a){return s.cancelInterest(id,a.getName());} @GetMapping("/items/{id}/interests/mine") public ExchangeService.InterestView myInterest(@PathVariable Long id,Authentication a){return s.myInterest(id,a.getName());} @GetMapping("/items/{id}/interests") public List<ExchangeService.InterestView> interests(@PathVariable Long id,Authentication a){return s.itemInterests(id,a.getName());}
 @PostMapping("/interests/{id}/confirm") public ExchangeService.HandoverView confirm(@PathVariable Long id,Authentication a){return s.confirm(id,a.getName());}
 @GetMapping("/handovers/mine") public List<ExchangeService.HandoverView> handovers(Authentication a){return s.myHandovers(a.getName());} @GetMapping("/handovers/{id}") public ExchangeService.HandoverView handover(@PathVariable Long id,Authentication a){return s.handover(id,a.getName());} @PostMapping("/handovers/{id}/cancel") public ExchangeService.HandoverView cancel(@PathVariable Long id,Authentication a){return s.cancelHandover(id,a.getName());} @PostMapping("/handovers/{id}/complete") public ExchangeService.HandoverView complete(@PathVariable Long id,Authentication a){return s.complete(id,a.getName());}
 @GetMapping("/items/{id}/comments") public List<ExchangeService.CommentView> comments(@PathVariable Long id){return s.comments(id);} @PostMapping("/items/{id}/comments") public ExchangeService.CommentView comment(@PathVariable Long id,@Valid @RequestBody CommentRequest b,Authentication a){return s.comment(id,b.content(),a.getName());} @PostMapping("/items/{itemId}/comments/{commentId}/replies") public ExchangeService.CommentView reply(@PathVariable Long itemId,@PathVariable Long commentId,@Valid @RequestBody CommentRequest b,Authentication a){return s.reply(itemId,commentId,b.content(),a.getName());}
 @GetMapping("/dashboard/mine") public ExchangeService.Dashboard dashboard(Authentication a){return s.dashboard(a.getName());}
 public record PickupRequest(@NotBlank @Size(max=200)String location,@NotEmpty @Size(max=5)List<ExchangeService.SlotInput> slots){} public record WantRequest(@NotNull Long slotId){} public record CommentRequest(@NotBlank @Size(max=500)String content){}
}